    int block_row = blockIdx.y;
    int block_col = blockIdx.x;

    // Thread indices within the block
    int thread_row = threadIdx.y;
    int thread_col = threadIdx.x;

    // Calculate the row and column indices of the element in C
    int row = block_row * TILE_SIZE + thread_row;
    int col = block_col * TILE_SIZE + thread_col;

    // Accumulator for this thread
    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile from A into shared memory
        int a_col = t * TILE_SIZE + thread_col;
        if (row < N && a_col < N) {
            A_tile[thread_row][thread_col] = A[row * N + a_col];
        } else {
            A_tile[thread_row][thread_col] = 0.0f;
