matrix_mult_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 16
#define REG_BLOCK_SIZE 4

__global__ void matrix_mult_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float A_tile[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float B_tile[BLOCK_SIZE][BLOCK_SIZE];

    // Block indices
    int block_row = blockIdx.y;
    int block_col = blockIdx.x;

    // Thread indices within the block
    int thread_row = threadIdx.y;
    int thread_col = threadIdx.x;

    // Calculate the starting row and column indices for the 4x4 output block
    int row_start = block_row * BLOCK_SIZE + thread_row * REG_BLOCK_SIZE;
    int col_start = block_col * BLOCK_SIZE + thread_col * REG_BLOCK_SIZE;

    // Registers for accumulating the 4x4 block
    float reg_C[REG_BLOCK_SIZE][REG_BLOCK_SIZE] = {{0.0f}};

    // Loop over tiles
    for (int t = 0; t < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; t++) {
        // Load tile from A into shared memory
        int a_col = t * BLOCK_SIZE + thread_col;
        if (row_start < N && a_col < N) {
            #pragma unroll
            for (int i = 0; i < REG_BLOCK_SIZE; i++) {
                int row = row_start + i;
                if (row < N) {
                    A_tile[thread_row * REG_BLOCK_SIZE + i][thread_col] = A[row * N + a_col];
                } else {
                    A_tile[thread_row * REG_BLOCK_SIZE + i][thread_col] = 0.0f;
                }
            }
        } else {
            #pragma unroll
            for (int i = 0; i < REG_BLOCK_SIZE; i++) {
                A_tile[thread_row * REG_BLOCK_SIZE + i][thread_col] = 0.0f;
            }
        }

        // Load tile from B into shared memory
        int b_row = t * BLOCK_SIZE + thread_row;
        if (b_row < N && col_start < N) {
            #pragma unroll
            for (int j = 0; j < REG_BLOCK_SIZE; j++) {
                int col = col_start + j;
                if (col < N) {
                    B_tile[thread_row][thread_col * REG_BLOCK_SIZE + j] = B[b_row * N + col];
                } else {
                    B_tile[thread_row][thread_col * REG_BLOCK_SIZE + j] = 0.0f;
                }
            }
        } else {
            #pragma unroll
            for (int j = 0; j < REG_BLOCK_SIZE; j++) {
                B_tile[thread_row][thread_col * REG_BLOCK_SIZE + j] = 0.0f;
            }
        }

        // Synchronize to ensure all tiles are loaded
        __syncthreads();

        // Compute partial product for this tile using register blocking
        #pragma unroll
        for (int k = 0; k < BLOCK_SIZE; k++) {
            float reg_A[REG_BLOCK_SIZE];
            float reg_B[REG_BLOCK_SIZE];

            // Load elements from shared memory to registers
            #pragma unroll
            for (int i = 0; i < REG_BLOCK_SIZE; i++) {
                reg_A[i] = A_tile[thread_row * REG_BLOCK_SIZE + i][k];
            }
            #pragma unroll
            for (int j = 0; j < REG_BLOCK_SIZE; j++) {
                reg_B[j] = B_tile[k][thread_col * REG_BLOCK_SIZE + j];
            }

            // Compute outer product
            #pragma unroll
            for (int i = 0; i < REG_BLOCK_SIZE; i++) {
                #pragma unroll
                for (int j = 0; j < REG_BLOCK_SIZE; j++) {
                    reg_C[i][j] += reg_A[i] * reg_B[j];
                }
            }
        }

        // Synchronize before next tile
        __syncthreads();
    }

    // Write result to C
    #pragma unroll
    for (int i = 0; i < REG_BLOCK_SIZE; i++) {
        #pragma unroll
        for (int j = 0; j < REG_BLOCK_SIZE; j++) {
            int row = row_start + i;
            int col = col_start + j;
            if (row < N && col < N) {
                C[row * N + col] = reg_C[i][j];
            }
        }
    }
}

